    public NatStar Min(NatStar o)
    {
        if (!IsTop && !o.IsTop) return Of(Math.Min(Value, o.Value));
        return IsTop ? o : this; // 一个为 ⊤ 时，min 取另一个（必为有限值或同为 ⊤）
    }

    // §3.1.5a compare：∀x∈ℕ*, x<⊤；⊤=⊤；无 x>⊤（类型不可直接表达，故为注释契约）。
    // 比较帮助器：先判 IsTop 再比较数值，避免任何 NaN。
