    {
        if (IsTop && o.IsTop) return 0;
        if (IsTop) return 1;   // ⊤ 最大
        if (o.IsTop) return -1;
        return Value.CompareTo(o.Value);
    }

    /// <summary>§3.1.5a 调试字符串（无代数语义，仅 ⊤ 或数值表示）。</summary>
    public override string ToString() => IsTop ? "⊤" : Value.ToString();
}

